:root {
  --main-color: blue;
}

h1 {
  color: var(--main-color);
}

/* Update using JavaScript */
document.documentElement.style.setProperty('--main-color', 'red');

/* Flexbox */
.parent {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 300px;
}

/* Grid */
.parent {
  display: grid;
  place-items: center;
  min-height: 300px;
}

#title {
  color: red;
}

.heading {
  color: blue;
}

h1 {
  color: green;
}

html {
  font-size: 16px;
}

.parent {
  font-size: 20px;
  width: 400px;
}

.child {
  font-size: 1.5em; /* 30px */
  width: 50%;       /* 200px */
  margin-top: 2rem; /* 32px */
}

/* Flexbox */
.container {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Grid */
.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.container {
  width: 80%;
  margin-inline: auto;
}

img {
  max-width: 100%;
  height: auto;
}

@media (max-width: 768px) {
  .container {
    width: 100%;
  }
}
